const DAY = 864e5;
const now = new Date();
const monday = new Date(now); monday.setHours(0, 0, 0, 0);
monday.setDate(monday.getDate() + ((8 - monday.getDay()) % 7 || 7));
const sunday = new Date(monday.getTime() + 7 * DAY);
const voice = String($('Read Brand voice').first().json.rules || '');
const bannedLine = (voice.match(/Banned:(.*)/i) || [, ''])[1];
const banned = ['cheapest in ibadan', 'cures', 'guaranteed', ...bannedLine.split(';')].map(s => s.trim().toLowerCase()).filter(Boolean);
const prices = $('Read Price list').all().map(i => i.json);
const top = $('Read Posts').all().map(i => i.json)
  .filter(p => p.published_at && new Date(p.published_at) > new Date(now - 7 * DAY))
  .sort((a, b) => (Number(b.reach) || 0) - (Number(a.reach) || 0)).slice(0, 3)
  .map(p => `${p.platform} · ${p.pillar} · reach ${p.reach}: ${String(p.caption).slice(0, 120)}`);
return $('Read Calendar').all().map(i => i.json)
  .filter(r => r.status !== 'drafted' && new Date(r.date) >= monday && new Date(r.date) < sunday)
  .map(r => {
    const product = prices.find(p => r.product && String(p.product).toLowerCase() === String(r.product).toLowerCase());
    return { json: { calendar_id: String(r.row_number), date: r.date, time: r.time, pillar: r.pillar, idea: r.idea,
      product: r.product || '', price: product ? product.price : '', stock: product ? product.stock : '',
      platforms: String(r.platforms).split(',').map(s => s.trim().toLowerCase()).filter(Boolean),
      media_file: r.media_file || '', brand_voice: voice, banned_phrases: banned, top_posts: top } };
  });

