// Card 3 checks plus the brand voice's banned phrases. Code decides; the AI only drafts.
const brief = $('One calendar item at a time').item.json;
const versions = ($json.output && $json.output.versions) || [];
const RULES = {
  facebook:  { max: 2000, tags: 3, media: false },
  instagram: { max: 2200, tags: 5, media: true },   // no text-only posts
  linkedin:  { max: 3000, tags: 3, media: false },
  x:         { max: 280,  tags: 2, media: false },
  tiktok:    { max: 2200, tags: 5, video: true },
  whatsapp:  { max: 1024, tags: 0, media: false },
};
const banned = brief.banned_phrases;
const hour = Number(String(brief.time || '').slice(0, 2));
const isVideo = /\.(mp4|mov)$/i.test(brief.media_file || '');
const checked = versions.filter(v => brief.platforms.includes(v.platform)).map(v => {
  const r = RULES[v.platform] || { max: 2000, tags: 3 };
  const full = v.caption + (v.hashtags.length ? '\n' + v.hashtags.map(h => '#' + h.replace(/^#/, '')).join(' ') : '');
  const problems = [];
  if (full.length > r.max) problems.push(`too long for ${v.platform} (${full.length}/${r.max})`);
  if (v.hashtags.length > r.tags) problems.push(`too many hashtags (${v.hashtags.length}/${r.tags})`);
  if (r.media && !brief.media_file) problems.push('Instagram needs a photo or video');
  if (r.video && !isVideo) problems.push('TikTok needs a video');
  if (v.platform === 'whatsapp' && brief.pillar !== 'Offers and dates') problems.push('WhatsApp is only for the weekly offer');
  if (!(hour >= 6 && hour <= 21)) problems.push(`posting time ${brief.time} is when nobody is online`);
  for (const b of banned) if (b && full.toLowerCase().includes(b)) problems.push(`banned phrase: ${b}`);
  const amounts = full.match(/₦\s?[\d,]+/g) || [];
  if (v.uses_price) {
    if (!brief.price) problems.push('uses a price but the product has no price in the sheet');
    else if (!amounts.length || amounts.some(a => a.replace(/[^\d]/g, '') !== String(brief.price).replace(/[^\d]/g, ''))) problems.push(`price must be ₦${brief.price} from the price list`);
  } else if (amounts.length) problems.push('mentions a price but uses_price is false');
  if (!v.alt_text) problems.push('missing alt text');
  return { ...v, full_caption: full, problems };
});
const missing = brief.platforms.filter(p => !checked.some(v => v.platform === p));
return { brief, versions: checked, missing, all_pass: !missing.length && checked.every(v => !v.problems.length) };

